CREATE SET TABLE MDP01_META.META_ETL_PARSED_COLUMN_LINEAGE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      parsed_lineage_id INTEGER NOT NULL,      etl_job_id INTEGER NOT NULL,      source_table_name VARCHAR(256) CHARACTER SET LATIN NOT CASESPECIFIC,      source_column_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      source_column_id INTEGER,      target_table_name VARCHAR(256) CHARACTER SET LATIN NOT CASESPECIFIC,      target_column_name VARCHAR(128) CHARACTER SET LATIN NOT CASESPECIFIC,      target_column_id INTEGER,      expression VARCHAR(4000) CHARACTER SET LATIN NOT CASESPECIFIC,      lineage_type VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      confidence VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      parsed_at TIMESTAMP(6),      parser_version VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      parsing_warnings VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( parsed_lineage_id )INDEX ( etl_job_id )INDEX ( source_column_id )INDEX ( target_column_id );